export const DARK_OAK_STAIRS = "dark_oak_stairs";
export const DARK_OAK_SLAB = "dark_oak_slab";
export const DARK_OAK_FENCE = "dark_oak_fence";
export const SPRUCE_TRAPDOOR = "spruce_trapdoor";
