export const FLOWERING_AZALEA_LEAVES = "flowering_azalea_leaves";
export const BIRCH_LOG = "birch_log";
export const BIRCH_LEAVES = "birch_leaves";
export const WHITE_TULIP = "white_tulip";
export const RED_TULIP = "red_tulip";
